QJsonObject cached(const QJsonObject& anchor,const QJsonObject& page){if(page["annotationLayoutId"]!=page["layoutId"])return {};auto hash=QString::fromLatin1(underlay::digest(QJsonDocument(anchor).toJson(QJsonDocument::Compact)).toHex());QJsonObject found;for(auto value:page["annotationResolutions"].toArray()){auto row=value.toObject();if(row["originalAnchorDigest"]!=hash)continue;if(!found.isEmpty()&&(found["status"]!=row["status"]||found["targetPage"]!=row["targetPage"]||found["fragments"]!=row["fragments"]))return {};found=row;}return found;}
struct Collapsed {QString text;std::vector<int> starts,ends;};
Collapsed whitespace(const QString& source){Collapsed out;out.text.reserve(source.size());out.starts.reserve(source.size());out.ends.reserve(source.size());for(int at=0;at<source.size();){const int begin=at;if(source[at].isSpace()){while(at<source.size()&&source[at].isSpace())++at;out.text+=' ';}else out.text+=source[at++];out.starts.push_back(begin);out.ends.push_back(at);}return out;}
