int sourcePage(const QJsonObject& anchor,const QJsonObject& page){if(anchor["document"]!=page["document"]||anchor["revision"]!=page["revision"]||anchor["format"]!=page["format"]||anchor["resolutionStatus"]=="unresolved")return -1;int target=-1;if(anchor["format"]=="pdf"||anchor["layoutId"]==page["layoutId"])target=anchor["page"].toInt(-1);else{auto row=cached(anchor,page);if(row["status"]=="resolved")target=row["targetPage"].toInt(-1);}return target>=0&&target<page["pages"].toInt(1000)?target:-1;}
