 if(anchor["format"]!="epub"||page["format"]!="epub")return fail("Unsupported annotation format");if(anchor["layoutId"]==page["layoutId"]&&anchor["page"]!=page["page"])return {{"status","other-page"}};if(anchor["layoutId"]!=page["layoutId"]){auto row=cached(anchor,page);if(row["status"]!="resolved")return fail("Verified source anchor unavailable after reflow");auto fragments=row["fragments"].toArray();if(fragments.isEmpty()){if(anchor["excerpt"].toString().isEmpty()&&row["targetPage"]==page["page"])return {{"status","resolved"},{"quads",QJsonArray{}},{"page",page["page"]}};return {{"status","other-page"}};}QJsonArray quads;int start=-1,end=-1;auto text=page["text"].toString();for(auto value:fragments){auto f=value.toObject();int first=f["first"].toInt(-1),last=f["last"].toInt(-1);if(f["page"]!=page["page"]||!f["first"].isDouble()||f["first"].toDouble()!=first||!f["last"].isDouble()||f["last"].toDouble()!=last||first<0||last<=first||last>text.size()||text.mid(first,last-first)!=f["text"].toString())return fail("Reflow fragment text changed");QJsonArray actual;for(auto glyph:page["chars"].toArray()){auto c=glyph.toObject();int offset=c["offset"].toInt(-1);if(offset>=first&&offset+c["text"].toString().size()<=last)actual.append(c["quad"]);}if(actual.isEmpty()||actual!=f["quads"].toArray())return fail("Reflow fragment geometry changed");for(auto q:actual)quads.append(q);if(start<0)start=first;end=last;}return {{"status","resolved"},{"quads",quads},{"page",page["page"]},{"start",start},{"end",end},{"matchPolicy","verified-immutable-epub-source-anchor"}};}const auto old=anchor["publicationLocation"].toObject(),current=page["publicationLocation"].toObject();
 const auto chapter=[](const QJsonObject& value){const auto number=value["chapter"];return number.isDouble()&&number.toInt(-1)>=0&&number.toDouble()==number.toInt(-1);};
